document.addEventListener('pointermove',event=>{const state=dragState;if(!state||event.pointerId!==state.pointerId)return;const dx=event.clientX-state.startX,dy=event.clientY-state.startY;if(!state.moved&&Math.hypot(dx,dy)<7)return;if(!state.moved){state.moved=true;state.el.setPointerCapture(event.pointerId);state.el.classList.add('owner-moving');document.documentElement.dataset.ownerDragging='';}event.preventDefault();state.last=event.altKey?boundedPoint(state.g,state.g.x+dx,state.g.y+dy):snapPoint(state,boundedPoint(state.g,state.g.x+dx,state.g.y+dy));state.el.style.translate=state.last.x+'px '+state.last.y+'px';updateSelectionFrame();}, {capture:true,passive:false});
