document.addEventListener('click',event=>{if(!active||busy||modal||event.target.closest('.inline-owner'))return;const el=event.target.closest('[data-direct-target]');if(!el)return;if(performance.now()<ignoreClickUntil){event.preventDefault();event.stopImmediatePropagation();return;}selectDeckItem(el);if(event.target.closest('[data-inline-text]')){if(el.matches('a'))event.preventDefault();return;}event.preventDefault();event.stopImmediatePropagation();directActions.get(el)?.();if(modal&&positionData()[el.dataset.positionKey])modal.append(button('Reset position',()=>{delete positionData()[el.dataset.positionKey];changed(pageFile);closeDialog();applyDirectPositions(drafts.get(pageFile));}));},true);
