let selectedElement=null,selectionFrame=null,selectionTools=null,selectionKey='',snapEnabled=true,rotationDrag=null;
function selectDeckItem(el){if(!el)return;selectedElement=el;if(getComputedStyle(el).display==='inline'){el.style.display='inline-block';el.dataset.ownerTransformDisplay='';}selectionKey=el.dataset.positionKey;if(!selectionFrame){selectionFrame=make('div');selectionFrame.className='inline-owner deck-selection';const move=make('span','Move');move.dataset.ownerMove='';move.className='deck-move-grip';move.title='Drag this border to move the text box or item';const rotate=make('span','↻');rotate.dataset.ownerRotate='';rotate.className='deck-rotate-grip';rotate.title='Drag to rotate';selectionFrame.append(move,rotate);document.body.append(selectionFrame);}showSelectionTools();updateSelectionFrame();}
