function showSelectionTools(){selectionTools?.remove();selectionTools=make('div');selectionTools.className='inline-owner deck-selection-tools';selectionTools.append(make('strong','Selected item'));for(const [label,axis]of [['Left','left'],['Center','center'],['Right','right'],['Top','top'],['Middle','middle'],['Bottom','bottom']])selectionTools.append(button(label,()=>alignSelected(axis)));selectionTools.append(button('Straighten',()=>rotateSelected(0)),button('Style',()=>editAnyItem(selectedElement)));if(selectedElement?.dataset.deckId)selectionTools.append(button('Edit',()=>editInserted(selectedElement.dataset.deckId)),button('Delete',()=>deleteInserted(selectedElement.dataset.deckId)));const angle=make('input');angle.type='number';angle.min='-180';angle.max='180';angle.value=drafts.get(pageFile).appearance?.transforms?.[selectionKey]?.rotation??0;angle.setAttribute('aria-label','Rotation in degrees');angle.onchange=()=>rotateSelected(designNumber(angle.value,-180,180,0));selectionTools.append(angle,make('span','°'),button(snapEnabled?'Guides: on':'Guides: off',()=>{snapEnabled=!snapEnabled;showSelectionTools();}));document.body.append(selectionTools);}
function rotateSelected(angle){if(!selectedElement)return;const data=drafts.get(pageFile);data.appearance??={};data.appearance.transforms??={};data.appearance.transforms[selectionKey]={rotation:Math.round(angle)};applyDeckTransforms(data);const angleInput=selectionTools?.querySelector('input');if(angleInput)angleInput.value=Math.round(angle);changed(pageFile);updateSelectionFrame();}
function alignSelected(axis){if(!selectedElement)return;const g=directGeometry(selectedElement);let x=g.x,y=g.y;if(axis==='left')x=g.b.left-g.left;if(axis==='center')x=g.b.left+(g.b.width-g.width)/2-g.left;if(axis==='right')x=g.b.right-g.width-g.left;if(axis==='top')y=g.b.top-g.top;if(axis==='middle')y=g.b.top+(g.b.height-g.height)/2-g.top;if(axis==='bottom')y=g.b.bottom-g.height-g.top;recordMove(selectedElement,boundedPoint(g,x,y));applyDirectPositions(drafts.get(pageFile));updateSelectionFrame();}
function hideGuides(){document.querySelectorAll('.deck-alignment-guide').forEach(el=>el.remove());}
function snapPoint(state,point){hideGuides();if(!snapEnabled)return point;const g=state.g,candidatesX=[g.b.left,g.b.left+g.b.width/2,g.b.right],candidatesY=[g.b.top,g.b.top+g.b.height/2,g.b.bottom];for(const other of document.querySelectorAll('[data-direct-target]')){if(other===state.el||other.contains(state.el)||state.el.contains(other)||directPositionBoundary(other)!==g.boundary)continue;const r=other.getBoundingClientRect();candidatesX.push(r.left,r.left+r.width/2,r.right);candidatesY.push(r.top,r.top+r.height/2,r.bottom);}const edgesX=[g.left+point.x,g.left+point.x+g.width/2,g.left+point.x+g.width],edgesY=[g.top+point.y,g.top+point.y+g.height/2,g.top+point.y+g.height];function nearest(edges,targets){let best=null;for(const edge of edges)for(const target of targets){const delta=target-edge;if(Math.abs(delta)<=6&&(!best||Math.abs(delta)<Math.abs(best.delta)))best={delta,target};}return best;}const sx=nearest(edgesX,candidatesX),sy=nearest(edgesY,candidatesY);if(sx)point.x+=sx.delta;if(sy)point.y+=sy.delta;for(const [axis,hit]of [['x',sx],['y',sy]]){if(!hit)continue;const guide=make('div');guide.className='inline-owner deck-alignment-guide '+axis;if(axis==='x')Object.assign(guide.style,{left:hit.target+'px',top:g.b.top+'px',height:g.b.height+'px'});else Object.assign(guide.style,{top:hit.target+'px',left:g.b.left+'px',width:g.b.width+'px'});document.body.append(guide);}return boundedPoint(g,point.x,point.y);}
function insertedHost(){return selectedElement?.closest('main>section')||document.querySelector('main>section');}
function insertDeck(type){const data=drafts.get(pageFile);data.appearance??={};data.appearance.objects??=[];const count=data.appearance.objects.length,host=insertedHost(),object={id:crypto.randomUUID(),host:host?.dataset.designKey,type,text:type==='emoji'?'✨':'Your text here',desktop:{xPercent:5+(count%5)*6,y:100+(count%5)*35+Math.floor(count/5)*80,width:type==='emoji'?90:240},mobile:{xPercent:5+(count%5)*6,y:100+(count%5)*35+Math.floor(count/5)*80,width:type==='emoji'?90:200}};editInserted(null,object);}
