document.addEventListener('pointerdown',event=>{if(!active||busy||modal)return;if(event.target.closest('[data-owner-rotate]')&&selectedElement){event.preventDefault();const r=selectedElement.getBoundingClientRect();rotationDrag={pointerId:event.pointerId,cx:r.left+r.width/2,cy:r.top+r.height/2,start:Math.atan2(event.clientY-(r.top+r.height/2),event.clientX-(r.left+r.width/2))*180/Math.PI,angle:drafts.get(pageFile).appearance?.transforms?.[selectionKey]?.rotation||0,target:event.target};event.target.setPointerCapture(event.pointerId);}},true);
document.addEventListener('pointermove',event=>{if(!rotationDrag||event.pointerId!==rotationDrag.pointerId)return;event.preventDefault();let angle=rotationDrag.angle+Math.atan2(event.clientY-rotationDrag.cy,event.clientX-rotationDrag.cx)*180/Math.PI-rotationDrag.start;angle=((angle+540)%360)-180;const snapped=Math.round(angle/15)*15;if(event.shiftKey||Math.abs(snapped-angle)<=3)angle=snapped;rotateSelected(angle);},{capture:true,passive:false});
